CREATE TABLE IF NOT EXISTS gis_asset_decision_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, analysis_request_id uuid REFERENCES gis_analysis_requests(id) ON DELETE SET NULL, spatial_status text NOT NULL DEFAULT 'Not Assessed', blocking_count integer NOT NULL DEFAULT 0, warning_count integer NOT NULL DEFAULT 0, community_hold boolean NOT NULL DEFAULT false, environmental_hold boolean NOT NULL DEFAULT false, legal_review_required boolean NOT NULL DEFAULT false, investment_impact text NOT NULL DEFAULT 'No Conclusion', rationale text, evidence_refs jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_decision_snapshots_asset ON gis_asset_decision_snapshots(asset_id,created_at DESC);
CREATE TABLE IF NOT EXISTS gis_rights_safeguards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, safeguard_type text NOT NULL, status text NOT NULL DEFAULT 'Required', blocking boolean NOT NULL DEFAULT true, rationale text NOT NULL, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_rights_safeguards_asset ON gis_rights_safeguards(asset_id,status,blocking);